#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_request_levels: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::RequestLevels>> = Mutex::new(None);
  pub static ref OUT_request_to_authorization: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts>> = Mutex::new(None);
  pub static ref OUT_request_to_lifecycle: Mutex<Option<Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_request_levels.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_request_to_authorization.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_request_to_lifecycle.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_request_levels(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::RequestLevels) -> bool
{
  unsafe {
    let guard = IN_request_levels.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_request_to_authorization(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts) -> bool
{
  unsafe {
    *OUT_request_to_authorization.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_request_to_lifecycle(value: *mut Vehicle_Start_Readiness_Recovery_Supervisor::RequestFacts) -> bool
{
  unsafe {
    *OUT_request_to_lifecycle.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
